// src7/plugins/programs/ChannelBridge.ts
 164    async getCallbackUrl(spec: specModule.ProgramSpec, signal: AbortSignal): Promise<string | undefined> {
 165      //G 没登记渠道的程序不回调；没挂 http 就没有地方收回调。
 166      if (spec.channels.length === 0 || this.app === undefined) return undefined;
 167  
 168      //M 最多等 startup_ms（和等就绪行一样长）；监听上了 address() 才有端口。
 169      const deadline = AbortSignal.timeout(spec.startupMs);
 170      let address = this.app.server.address();
 171      while (address === null) {
 172        //G 等太久就当这次启动失败，交给 Host 退避重试，不一直卡在启动中。
 173        if (deadline.aborted) throw new Error(`主服务一直没开始监听，拿不到回调地址（等了 ${String(spec.startupMs)} 毫秒）`);
 174  
 175        //M 每 100 毫秒看一次主服务监听上没有。
 176        await timers.setTimeout(100, undefined, { signal });
 177        address = this.app.server.address();
 178      }
 179  
 180      //G 监听在管道上（不会这样配）就没有可回调的端口。
 181      if (typeof address === 'string') return undefined;
 182  
 183      //M 主服务监听全部地址（0.0.0.0、::）时程序走本机回环，本机来的请求 http 插件不查主令牌。
 184      let host = address.address;
 185      if (host === '0.0.0.0' || host === '::') host = '127.0.0.1';
 186      if (host.includes(':')) host = `[${host}]`;
 187      return `http://${host}:${String(address.port)}/api/programs/${spec.name}`;
 188    }
```

