// src7/plugins/programs/Protocol.ts
 168  function parseReady(line: string, spec: ProgramSpec): ReadyLine | undefined {
 169    let decoded: unknown;
 170    try {
 171      decoded = JSON.parse(line);
 172    } catch {
 173      return undefined;
 174    }
 175    if (typeof decoded !== 'object' || decoded === null) return undefined;
 176  
 177    const raw = decoded as Record<string, unknown>;
 178    const protocol = raw['jmbots'];
 179    if (typeof protocol !== 'number') return undefined;
 180  
 181    //G 版本不兼容时阻止自动重试，等用户换正确的程序。
 182    if (protocol !== PROTOCOL) {
 183      throw new UnsupportedProtocol(`协议版本不对（程序 ${String(protocol)}，jmbots 支持 ${String(PROTOCOL)}）`);
 184    }
 185    if (raw['event'] !== 'ready' || raw['name'] !== spec.name) {
 186      throw new Error(`就绪行的事件或程序名和 ${spec.name} 不符`);
 187    }
 188    const version = raw['version'];
 189    if (typeof version !== 'string' || version.trim() === '') throw new Error('就绪行缺少程序版本');
 190  
 191    const port = raw['port'];
 192    if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535) {
 193      throw new Error('就绪行端口要是 1 至 65535 的整数');
 194    }
 195    if (spec.port !== 0 && port !== spec.port) throw new Error(`就绪行端口与配置 ${String(spec.port)} 不符`);
 196  
 197    return { version, port };
 198  }
```

### 解释
- Host L431：`waitReady` 等就绪行，超过 `startup_ms` 就算启动失败。
- Protocol L178–L184：协议版本不对抛 `UnsupportedProtocol`，状态改 blocked，不再自动重试。
- Protocol L185–L195：
  - 事件不是 ready、名字不符，抛错；
  - 缺版本，抛错；
  - 端口不合法，或和配置的固定端口不同，抛错。

