// src7/plugins/programs/Protocol.ts
 248  export async function readReport(
 249    url: string, name: string, route: 'info' | 'health', timeoutMs: number, signal: AbortSignal,
 250  ): Promise<ProgramReport | undefined> {
 251    const endpoint = `${url}/jmbots/v1/${route}`;
 252    const timeout = AbortSignal.timeout(timeoutMs);
 253    const until = AbortSignal.any([signal, timeout]);
 254    const options: RequestInit = { signal: until, redirect: 'error' };
 255    try {
 256      //M 只信已核对协议与程序名的回执，不让错误服务提供资源排行或暂停能力。
 257      const response = await fetch(endpoint, options);
 258      const decoded: unknown = await response.json();
 259      if (!response.ok || typeof decoded !== 'object' || decoded === null) return undefined;
 260  
 261      const raw = decoded as Record<string, unknown>;
 262      if (raw['ok'] !== true || raw['protocol'] !== PROTOCOL || raw['name'] !== name) return undefined;
 263  
 264      const capabilities = raw['capabilities'];
 265      const pause = Array.isArray(capabilities) && capabilities.includes('pause');
 266      let rssMb: number | undefined;
 267      const rss = raw['rssMb'];
 268      if (typeof rss === 'number' && Number.isFinite(rss) && rss >= 0) {
 269        rssMb = rss;
 270      }
 271      //M 界面只接受程序内部路径，不接受任意主机、端口或脚本URL。
 272      const ui = getUiPath(raw['ui']);
 273      return { pause, rssMb, ui };
 274    } catch {
 275      return undefined;
 276    }
 277  }
```

