 506    private async watchHealth(endpoint: string, signal: AbortSignal): Promise<void> {
 507      let misses = 0;
 508      let licenseAt = Date.now();
 509      const wait = { signal };
 510      while (!signal.aborted) {
 511        await timers.setTimeout(this.timing.watchMs, undefined, wait);
 512  
 513        //M 独立探测健康接口，连接失败与身份不符都算一次失败。
 514        const report = await protocolModule.readReport(
 515          endpoint, this.spec.name, 'health', this.timing.healthMs, signal,
 516        );
 517        signal.throwIfAborted();
 518        if (report !== undefined) {
 519          this.rssMb = report.rssMb;
 520          this.rssAt = Date.now();
 521          if (Date.now() - licenseAt >= 60_000) {
 522            //M 每分钟更新一次授权，缺接口或失败保持未知，不把未知当未授权。
 523            this.license = await protocolModule.readLicense(endpoint, signal);
 524            signal.throwIfAborted();
 525            licenseAt = Date.now();
 526            //M 授权状态变化单独广播，不把授权到期当停机。
 527            this.publishState();
 528          }
 529          misses = 0;
 530          this.note = '在运行';
 531          continue;
 532        }
 533        misses += 1;
 534        this.note = `健康检查连续失败 ${String(misses)} 次`;
 535        if (misses >= this.timing.healthMisses) {
 536          this.state = 'unhealthy';
 537          //M 健康异常不再提供ready入口，后续正常停止/重试由监督处理。
